recipe:
vars:
  site: {default: a.test}
  root: {default: "/www/${site}"}
steps:
  - run: [echo, "${root}"]

vars:
  _a1: {default: x}
  Site_Name: {default: y}
steps:
  - run: [echo, "${_a1}${Site_Name}"]

vars:
  site: {default: a.test}
  mode: {default: "0640"}
steps:
  - file:
      path: /usr/local/etc/${site}.conf
      content: x
      mode: ${mode}

vars:
  d: {default: /var/db/x}
steps:
  - dir: {path: "${d}", mode: "0750", owner: root}

vars:
  pw: {required: true, secret: true}
steps:
  - file: {path: /usr/local/etc/a, template: true, content: "${pw}"}

vars:
  pw: {secret: true}
steps:
  - file: {path: /usr/local/etc/a, template: true, content: "${pw}"}

vars:
  pw: {secret: true}
steps:
  - file: {path: /usr/local/etc/a, template: true, content: "${pw}"}

vars:
  pw: {secret: true}
steps:
  - file: {path: "/usr/local/etc/${pw}", content: x}

vars:
  pw: {secret: true}
steps:
  - file: {path: /usr/local/etc/a, source: "${pw}"}

vars:
  pw: {secret: true}
  other: {default: "${pw}"}
steps:
  - file: {path: /usr/local/etc/a, template: true, content: "${other}"}

vars:
  pw: {secret: true}
steps:
  - file: {path: /usr/local/etc/a, content: "${pw}"}
